// Opt-in live check (NEKO_LIVE_WHISPER=1): neko-asr sidecar with the upstream
// faster_whisper worker (local, base model) transcribes a zh utterance
// generated by Windows SAPI, and exactly one final reaches commitTurn.
// Audio is synthetic; nothing leaves the machine except the one-time model
// download from Hugging Face into services/neko-asr/models/.
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";

import { SidecarAsrProvider, startAsrSidecar } from "../../packages/voice-adapter/src/asr-sidecar.ts";
import { AsrInput } from "../../packages/voice-adapter/src/asr.ts";
import type { Receipt } from "../../packages/memory-adapter/src/memory-client.ts";
import type { MemoryTurn } from "../../packages/app-contracts/src/index.ts";
import { ConversationTurns, attachVoiceTurns } from "../../packages/app-coordinator/src/voice-turn.ts";

const LIVE = process.env.NEKO_LIVE_WHISPER === "1";
const PORT = 59069;
const PHRASE = "今天天气很好，我们去公园散步吧。";

/** Synthesize PHRASE with SAPI (zh-CN voice) as 16 kHz mono PCM16 WAV. */
function synthesize(wavPath: string): void {
  const script = [
    "Add-Type -AssemblyName System.Speech",
    "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer",
    "$v = $s.GetInstalledVoices() | Where-Object { $_.VoiceInfo.Culture.Name -eq 'zh-CN' } | Select-Object -First 1",
    "if (-not $v) { throw 'no zh-CN SAPI voice installed' }",
    "$s.SelectVoice($v.VoiceInfo.Name)",
    "$fmt = New-Object System.Speech.AudioFormat.SpeechAudioFormatInfo(16000, [System.Speech.AudioFormat.AudioBitsPerSample]::Sixteen, [System.Speech.AudioFormat.AudioChannel]::Mono)",
    "$s.SetOutputToWaveFile($env:F10_WAV, $fmt)",
    "$s.Speak($env:F10_PHRASE)",
    "$s.Dispose()",
  ].join("; ");
  execFileSync("powershell.exe", ["-NoProfile", "-NonInteractive", "-Command", script], {
    env: { ...process.env, F10_WAV: wavPath, F10_PHRASE: PHRASE },
    stdio: ["ignore", "pipe", "pipe"],
  });
}

/** PCM16 payload of a RIFF/WAVE file (the "data" chunk). */
function wavPcm(path: string): Uint8Array {
  const buf = readFileSync(path);
  let off = 12;
  while (off + 8 <= buf.length) {
    const id = buf.toString("ascii", off, off + 4);
    const size = buf.readUInt32LE(off + 4);
    if (id === "data") return new Uint8Array(buf.buffer, buf.byteOffset + off + 8, Math.min(size, buf.length - off - 8));
    off += 8 + size + (size % 2);
  }
  throw new Error("WAV has no data chunk");
}

test("asr-whisper-live: SAPI zh wav -> faster_whisper -> one commitTurn", { skip: !LIVE && "set NEKO_LIVE_WHISPER=1" }, async () => {
  const dir = mkdtempSync(join(tmpdir(), "f10-whisper-live-"));
  const proc = await startAsrSidecar({ port: PORT, provider: "faster_whisper" });
  const asr = new AsrInput(new SidecarAsrProvider({ url: proc.ws_url, language: "zh" }), {
    // First run includes model download and load.
    final_timeout_ms: 600_000,
  });
  try {
    const wav = join(dir, "phrase.wav");
    synthesize(wav);
    const pcm = wavPcm(wav);
    const audioSeconds = pcm.byteLength / 32_000;

    const committed: MemoryTurn[] = [];
    const memory = {
      async commitTurn(turn: MemoryTurn): Promise<Receipt> {
        committed.push(turn);
        return { kind: "submitted", receipt_id: "r1", turn_id: turn.turn_id, character_id: turn.character_id, submitted_at: "", status: "pending" };
      },
    };
    const turns = new ConversationTurns(memory, { character_id: "character_0f10a000000000000000000000000002", scope: "user" });
    const binding = attachVoiceTurns({
      asr,
      turns,
      respond: async () => ({ assistant_text: "好呀", assistant_delivery: "text_only" }),
    });

    // Warm-up utterance loads (and on first run downloads) the model.
    const warmStart = Date.now();
    const warm = asr.startRecording("warmup");
    warm.pushAudio(new Uint8Array(16_000));
    await warm.stop();
    const warmMs = Date.now() - warmStart;
    await sleep(50);
    committed.length = 0;

    const handle = asr.startRecording("utt-live");
    const FRAME = 3_200; // 100 ms
    for (let i = 0; i < pcm.byteLength; i += FRAME) handle.pushAudio(pcm.subarray(i, i + FRAME));
    const t0 = Date.now();
    const result = await handle.stop();
    const latencyMs = Date.now() - t0;
    await binding.settled("utt-live");
    await sleep(200);

    console.log(
      `asr-whisper-live: audio=${audioSeconds.toFixed(2)}s warmup=${warmMs}ms stop->final=${latencyMs}ms result=${JSON.stringify(result)}`,
    );
    assert.equal(result.kind, "final", JSON.stringify(result));
    const voice = committed.filter((t) => t.utterance_id === "utt-live");
    assert.equal(voice.length, 1, "exactly one final committed");
    const text = voice[0]!.user_text;
    assert.equal(voice[0]!.source_kind, "voice");
    // Loose content check: whisper base often answers zh in Traditional script.
    const keywords = [["天气", "天氣"], ["公园", "公園"], ["散步"]];
    const hits = keywords.filter((variants) => variants.some((w) => text.includes(w)));
    assert.ok(hits.length >= 2, `transcript "${text}" should contain most of the phrase keywords`);
    binding.detach();
  } catch (err) {
    console.log("=== neko-asr ===\n", proc.output().slice(-4000));
    throw err;
  } finally {
    await asr.close();
    await proc.stop();
    rmSync(dir, { recursive: true, force: true });
  }
});
